.vault-shake{animation:vaultShake .28s linear 1}
@keyframes partyTwinkle{0%,100%{opacity:1;filter:brightness(1.2)}50%{opacity:.45;filter:brightness(.7)}}
.party-bulb{animation:partyTwinkle 1.6s ease-in-out infinite}
@keyframes partyFlicker{0%,100%{opacity:.95}40%{opacity:.75}55%{opacity:1}80%{opacity:.82}}
.party-win{animation:partyFlicker 2.8s ease-in-out infinite}
@keyframes partySway{0%,100%{transform:translateX(0)}50%{transform:translateX(10px)}}
.party-guest{animation:partySway 1.3s ease-in-out infinite}
@keyframes partyKnock{0%,100%{transform:rotateY(0deg) translateX(0)}20%{transform:rotateY(0deg) translateX(-3px)}40%{transform:rotateY(0deg) translateX(2px)}60%{transform:rotateY(0deg) translateX(-3px)}80%{transform:rotateY(0deg) translateX(2px)}}
.party-knock{animation:partyKnock .45s linear 2}
@keyframes partySpill{0%{opacity:0;transform:scale(.6)}100%{opacity:1;transform:scale(1.25)}}
.party-spill{animation:partySpill 1.6s ease-out both}
@keyframes partyPop{0%{opacity:0;transform:translate(0,0) rotate(0deg)}15%{opacity:1}100%{opacity:0;transform:translate(var(--dx),var(--dy)) rotate(540deg)}}
.party-pop{animation:partyPop 1.9s cubic-bezier(.15,.6,.3,1) both}
@keyframes partyIn{from{opacity:0;transform:translateY(14px) scale(.97)}to{opacity:1;transform:none}}
.party-in{animation:partyIn .7s ease-out both}
.party-knockbtn:hover{filter:brightness(1.1)}
@media (max-width:560px){.m-pwin{display:none!important}.m-pscene{min-height:440px!important}}
@media (prefers-reduced-motion: reduce){.party-bulb,.party-win,.party-guest,.party-knock,.party-spill,.party-pop,.party-in{animation:none!important}}

// The party door: two knocks, a short creak, then a bright chord as the party comes into view.
partySound(step) {
try {
const C = window.AudioContext || window.webkitAudioContext;
if (!C) return;
const ctx = this.actx || (this.actx = new C());
if (ctx.state === "suspended") ctx.resume();
const t0 = ctx.currentTime;
const thud = (when) => {
const n = Math.floor(ctx.sampleRate * 0.12), buf = ctx.createBuffer(1, n, ctx.sampleRate), d = buf.getChannelData(0);
for (let k = 0; k < n; k++) d[k] = (Math.random() * 2 - 1) * Math.pow(1 - k / n, 6);
const s = ctx.createBufferSource(), f = ctx.createBiquadFilter(), a = ctx.createGain();
s.buffer = buf; f.type = "lowpass"; f.frequency.value = 420; a.gain.value = 1.4;
s.connect(f); f.connect(a); a.connect(ctx.destination); s.start(t0 + when);
};
const tone = (fr, when, dur, g, type) => {
const o = ctx.createOscillator(), a = ctx.createGain();
o.type = type || "triangle"; o.frequency.value = fr;
a.gain.setValueAtTime(0.0001, t0 + when); a.gain.exponentialRampToValueAtTime(g, t0 + when + 0.03); a.gain.exponentialRampToValueAtTime(0.0001, t0 + when + dur);
o.connect(a); a.connect(ctx.destination); o.start(t0 + when); o.stop(t0 + when + dur + 0.05);
};
if (step === "knock") { thud(0); thud(0.22); thud(0.62); thud(0.84); }
if (step === "open") {
const o = ctx.createOscillator(), a = ctx.createGain();
o.type = "sawtooth"; o.frequency.setValueAtTime(140, t0); o.frequency.linearRampToValueAtTime(95, t0 + 0.7);
a.gain.setValueAtTime(0.0001, t0); a.gain.exponentialRampToValueAtTime(0.03, t0 + 0.1); a.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.75);
o.connect(a); a.connect(ctx.destination); o.start(t0); o.stop(t0 + 0.8);
[523.25, 659.25, 783.99, 1046.5].forEach((fr, k) => tone(fr, 0.75 + k * 0.09, 1.4, 0.09));
}
} catch (e) { /* sound is a nice extra only */ }
}
